#include <stdio.h>

typedef struct { int num; char name[32], address[101]; } Student;

int main(void) {
    Student students[3];
    for (Student *p = students; p < students + 3; p++) scanf("%d%31s%100s", &p->num, p->name, p->address);
    for (Student *p = students; p < students + 3; p++) printf("%d %s %s\n", p->num, p->name, p->address);
    return 0;
}
